  const catalog = new Set(
    [
      ...detranSource.matchAll(/'([^']+)'/g),
      ...detranSource.matchAll(/\.\.\.(\w+)/g),
    ].flatMap((match) => arrays.get(match[1]) ?? [match[1]]),
  );
  for (const role of defaults) {
    assert.ok(catalog.has(role), `${role} belongs to DETRAN_ROLES`);
  }
});

